function [net, coralBias] = buildCoralTrainNet(backboneName, opts)
%BUILDCORALTRAINNET  CORAL ordinal model, built so it stays code-generable.
%
%   WHY THIS IS SHAPED THE WAY IT IS
%   --------------------------------
%   True CORAL (Cao et al.) guarantees rank-monotone outputs by giving the
%   K-1 binary tasks a SHARED weight vector and INDEPENDENT biases:
%
%       logit_k = w'*f + b_k        k = 1..K-1,  b_1 >= b_2 >= ... (learned)
%
%   The obvious MATLAB implementation is a custom layer holding b. Custom
%   layers cannot be code-generated by MATLAB Coder, which would kill the
%   Raspberry Pi path.
%
%   So instead:
%     * the NETWORK ends at fullyConnectedLayer(1)  -> produces w'*f
%     * the bias vector b lives OUTSIDE the network as a plain dlarray
%       learnable, updated in the custom training loop
%     * after training, ophira.models.expandCoralHead folds w and b into an
%       ordinary fullyConnectedLayer(K-1) + sigmoidLayer
%
%   The expanded network is mathematically identical, still rank-monotone
%   (all rows of the weight matrix are the same w), and built entirely from
%   built-in, codegen-supported layers.
%
%   [net, coralBias] = ophira.models.buildCoralTrainNet("efficientnetb0", ...
%                           Size=512, NumClasses=5)

arguments
    backboneName (1,1) string
    opts.Size       (1,1) double = 512
    opts.NumClasses (1,1) double = 5
    opts.Pretrained (1,1) logical = true
    opts.UseSE      (1,1) logical = false   % squeeze-excitation channel attention
    opts.SERatio    (1,1) double  = 16
end

K = opts.NumClasses;

[bb, bbInfo] = ophira.models.buildBackbone(backboneName, ...
    Size=opts.Size, Pretrained=opts.Pretrained);

lg      = layerGraph(bb);
lastOut = bb.OutputNames{1};

% --- optional squeeze-and-excitation channel attention -------------------
% Built from built-in layers ONLY (globalAvgPool/fc/relu/fc/sigmoid/multiply)
% so it remains codegen-safe. Spatial attention is deliberately NOT offered:
% it needs channel-wise pooling, which has no built-in layer.
if opts.UseSE
    C = ophira.models.channelCount(bb, opts.Size);
    se = [
        globalAveragePooling2dLayer(Name="se_gap")
        fullyConnectedLayer(max(4, floor(C/opts.SERatio)), Name="se_fc1")
        reluLayer(Name="se_relu")
        fullyConnectedLayer(C, Name="se_fc2")
        sigmoidLayer(Name="se_sig")];
    lg = addLayers(lg, se);
    lg = addLayers(lg, multiplicationLayer(2, Name="se_scale"));
    lg = connectLayers(lg, lastOut, "se_gap");
    lg = connectLayers(lg, lastOut, "se_scale/in1");
    lg = connectLayers(lg, "se_sig", "se_scale/in2");
    lastOut = "se_scale";
end

% --- CORAL trunk: pool to a vector, project to a SINGLE shared logit ------
head = [
    globalAveragePooling2dLayer(Name="gap")
    dropoutLayer(0.2, Name="drop")
    fullyConnectedLayer(1, Name="coral_shared", BiasLearnRateFactor=0)];
%       ^ bias forced off: the per-task biases live in coralBias instead,
%         otherwise the model would be over-parameterised by a constant.

lg  = addLayers(lg, head);
lg  = connectLayers(lg, lastOut, "gap");
net = dlnetwork(lg);

% --- the K-1 independent bias terms, as a trainable dlarray -------------
% Initialised decreasing so the model starts rank-monotone.
b0        = linspace(1, -1, K-1);
coralBias = dlarray(single(b0(:)'));     % 1 x (K-1)

fprintf(['CORAL train-net built: %s @ %d px, K=%d, SE=%d, %.2fM learnables ' ...
         '(+%d CORAL biases)\n'], ...
    backboneName, opts.Size, K, opts.UseSE, bbInfo.num_learnables/1e6, K-1);
end
